{
  "name": "@adastracomputing/aer-hooks",
  "version": "0.13.3",
  "description": "Fail-open, redaction-by-default hook adapters that record the tool events a coding harness fires (Claude Code, OpenAI Codex CLI, Antigravity) or its plugins load (opencode) into AER. Tool and argument-key names only by default, never values.",
  "type": "module",
  "private": false,
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "bin": {
    "aer-hook": "./dist/cli.js",
    "aer-hooks": "./dist/install-cli.js"
  },
  "files": [
    "dist/**/*.js",
    "dist/**/*.d.ts",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "license": "Apache-2.0",
  "author": "Ad Astra Computing",
  "homepage": "https://aer.run",
  "repository": {
    "type": "git",
    "url": "https://github.com/Ad-Astra-Computing/aer.git",
    "directory": "packages/aer-hooks"
  },
  "bugs": {
    "url": "https://github.com/Ad-Astra-Computing/aer/issues"
  },
  "keywords": [
    "aer",
    "agent",
    "claude-code",
    "codex",
    "opencode",
    "hooks",
    "observability"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@adastracomputing/aer-emit": "0.5.1"
  },
  "devDependencies": {
    "@types/node": "^22.20.4",
    "typescript": "^7.0.2",
    "vitest": "^4.1.11"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "prebuild": "node scripts/write-version.mjs",
    "build": "tsc -p tsconfig.json",
    "pretest": "node scripts/write-version.mjs",
    "test": "vitest run",
    "pretypecheck": "node scripts/write-version.mjs",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  }
}
